with account_totals as (select account_id, sum(case when txn_type = 'FEE' then 1 else 0 end) as fee_count, max(txn_time) as last_txn_time from transactions group by account_id) select accounts.id, accounts.account_type, account_totals.fee_count, account_totals.last_txn_time from accounts inner join account_totals on accounts.id = account_totals.account_id order by account_totals.last_txn_time, account_type
